@sig trait ShipReportAcquisition_Api {
  def id: Art.BridgeId
  def ship_report_Id : Art.PortId
  def ship_report_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var ship_report_facts: Mining_Cargo_Transfer_Evidence_Coordinator.ShipReportFacts = $

  def put_ship_report_facts(value : Mining_Cargo_Transfer_Evidence_Coordinator.ShipReportFacts) : Unit = {
    Contract(
      Modifies(ship_report_facts),
      Ensures(
        ship_report_facts == value
      )
    )
    Spec {
      ship_report_facts = value
    }

    Art.putValue(ship_report_facts_Id, Mining_Cargo_Transfer_Evidence_Coordinator.ShipReportFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ShipReportAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val ship_report_Id : Art.PortId,
  val ship_report_facts_Id : Art.PortId) extends ShipReportAcquisition_Api

@datatype class ShipReportAcquisition_Operational_Api (
  val id: Art.BridgeId,
  val ship_report_Id : Art.PortId,
  val ship_report_facts_Id : Art.PortId) extends ShipReportAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var ship_report: Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport.Type = $

  def get_ship_report() : Option[Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport.Type] = {
    Contract(
      Ensures(
        Res == Some(ship_report)
      )
    )
    val value : Option[Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport.Type] = Art.getValue(ship_report_Id) match {
      case Some(Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port ship_report.  Expecting 'Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport_Payload' but received ${v}")
        None[Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport.Type]()
      case _ => None[Mining_Cargo_Transfer_Evidence_Coordinator.ShipReport.Type]()
    }
    return value
  }
}
